static uint16_t psx_ov_last_hit[19054];
static uint64_t psx_ov_entry_hits[19054];

/* 19054 dispatch addresses, 34846 variants, 65536-slot table (load 0.29), max probe 7. */
#define PSX_OV_HASH_MASK 0xFFFFu

static inline uint32_t psx_ov_hash_slot(uint32_t key) {
    uint32_t h = key >> 2;            /* entries are word-aligned */
    h *= 0x9E3779B1u;
    h ^= h >> 15;
    return h & PSX_OV_HASH_MASK;
}

void psx_overlay_static_get_stats(uint64_t *checks, uint64_t *hits,
                                  uint64_t *variant_misses,
                                  uint64_t *address_misses) {
    if (checks) *checks = psx_ov_static_checks;
    if (hits) *hits = psx_ov_static_hits;
    if (variant_misses) *variant_misses = psx_ov_static_variant_misses;
    if (address_misses) *address_misses = psx_ov_static_address_misses;
}

/* Entry index of the last successful find (single-threaded dispatch). */
static uint32_t psx_ov_found_entry = 0;

static const PsxOvVariant *psx_overlay_static_find_variant(uint32_t addr) {
    /* Entries are the KSEG0 PCs their bodies were compiled for
     * (PSX_OVERLAY_CODE_SEGMENT, overlay_loader.h). A KUSEG or KSEG1
     * alias of the same bytes is a different architectural PC and
     * stays in the interpreter. */
    if ((addr & 0xE0000000u) != 0x80000000u) {
        psx_ov_static_address_misses++;
        return 0;
    }
    const uint32_t key = addr;
    uint32_t slot = psx_ov_hash_slot(key);
    for (;;) {
        uint32_t slot_addr = psx_ov_hash_addr[slot];
        if (slot_addr == 0u) {
            /* Empty slot: this address is compiled nowhere. This is
             * the overwhelmingly common case -- keep it one load. */
            psx_ov_static_address_misses++;
            return 0;
        }
        if (slot_addr == key) break;
        slot = (slot + 1u) & PSX_OV_HASH_MASK;
    }
    {
        const uint32_t ei = psx_ov_hash_idx[slot];
        const PsxOvEntry *e = &psx_ov_entries[ei];
        const PsxOvVariant *base = &psx_ov_variants[e->first];
        const uint32_t n = e->n;
        uint32_t memo = psx_ov_last_hit[ei];
        uint32_t i;
        if (memo >= n) memo = 0u;
        /* Try the occupant that satisfied this address last time. On a
         * deep band this is the difference between one CRC gate and
         * walking every occupant. It is only a hint: the gate below
         * still decides, so a swapped band simply falls through. */
        if (n > 1u) {
            const PsxOvVariant *v = base + memo;
            psx_ov_static_checks++;
            if (psx_overlay_static_code_matches(v->ranges, v->count,
                                               v->crc)) {
                psx_ov_found_entry = ei;
                return v;
            }
            psx_ov_static_variant_misses++;
        }
        for (i = 0; i < n; i++) {
            const PsxOvVariant *v = base + i;
            if (n > 1u && i == memo) continue;   /* already tried */
            psx_ov_static_checks++;
            if (psx_overlay_static_code_matches(v->ranges, v->count,
                                               v->crc)) {
                psx_ov_last_hit[ei] = (uint16_t)i;
                psx_ov_found_entry = ei;
                return v;
            }
            psx_ov_static_variant_misses++;
        }
    }
    /* Address is ours but no occupant is resident -> interpreter. */
    return 0;
}

int psx_overlay_static_can_dispatch(uint32_t addr) {
    return psx_overlay_static_find_variant(addr) != 0;
}

int psx_overlay_dispatch(CPUState *cpu, uint32_t addr) {
    const PsxOvVariant *v = psx_overlay_static_find_variant(addr);
    if (!v) return 0;
    psx_ov_static_hits++;
    psx_ov_entry_hits[psx_ov_found_entry]++;
    v->fn(cpu);
    return 1;
}

uint32_t psx_overlay_static_entry_count(void) { return 19054u; }

/* Entry `index` (sorted by address): its address, occupant count and
 * dispatches served. 0 past the last entry. */
int psx_overlay_static_entry_stats(uint32_t index, uint32_t *addr,
                                   uint32_t *variants, uint64_t *hits) {
    if (index >= 19054u) return 0;
    if (addr) *addr = psx_ov_entries[index].addr;
    if (variants) *variants = psx_ov_entries[index].n;
    if (hits) *hits = psx_ov_entry_hits[index];
    return 1;
}
